import{_ as i,C as e,o as d,c as n,E as a,a2 as s}from"./chunks/framework.Cc8dJFaW.js";const b=JSON.parse('{"title":"拦下一次越权写入之后，谁负责下一次？","description":"","frontmatter":{"title":"拦下一次越权写入之后，谁负责下一次？","article_type":"comparative-study","edition":"research-center","research_question":"一次纠正性拦截与逐次绑定裁决在同轮重试中有什么不同？","summary":"一次纠正与逐次拒绝承担不同责任。结合两份独立撰写的来源与内部状态模型，检查重试是否仍经过授权裁决，并保留真实宿主尚未验证的边界。","sources":"https://arxiv.org/html/2608.19861v2, https://github.com/microsoft/agent-governance-toolkit","date":"2026-11-28","column":"industry-architecture","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261128-001","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-28-sig-20261128-001-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-11-28-sig-20261128-001.md","filePath":"zh/industry/2026-11-28-sig-20261128-001.md","lastUpdated":null}'),l={name:"zh/industry/2026-11-28-sig-20261128-001.md"};function c(h,t,p,u,m,_){const r=e("ArticleCover"),o=e("ArticleTableScroll");return d(),n("div",null,[a(r,{image:"/assets/covers/daily-2026-11-28-sig-20261128-001-cover.png",kicker:"研究成果",title:"拦下一次越权写入之后，谁负责下一次？",summary:"一次纠正与逐次拒绝承担不同责任。结合两份独立撰写的来源与内部状态模型，检查重试是否仍经过授权裁决，并保留真实宿主尚未验证的边界。",version:"2026-11-28",languageHref:"/en/industry/2026-11-28-sig-20261128-001",languageLabel:"English"}),a(o,{language:"zh"}),t[0]||(t[0]=s('<h1 id="拦下一次越权写入之后-谁负责下一次" tabindex="-1">拦下一次越权写入之后，谁负责下一次？ <a class="header-anchor" href="#拦下一次越权写入之后-谁负责下一次" aria-label="Permalink to &quot;拦下一次越权写入之后，谁负责下一次？&quot;">​</a></h1><p>一个写入请求被拦下，同一轮对话里的第二次尝试却被允许继续。这不是虚构的产品事故，而是已读论文明确报告的纠正策略：首次干预后暂时解除拦截，给执行者留出修正空间。平台工程师需要区分两个承诺：帮助执行者改正，与持续阻止未经授权的副作用。检查重试路径由谁裁决，比只看首次拒绝更有用。</p><h2 id="纠正策略主动留下了什么空间" tabindex="-1">纠正策略主动留下了什么空间 <a class="header-anchor" href="#纠正策略主动留下了什么空间" aria-label="Permalink to &quot;纠正策略主动留下了什么空间&quot;">​</a></h2><p>PolicyGuide（策略引导研究系统）论文第 3.4 节描述的建议式模式，在一个用户轮次内移除首个不符合当前流程状态的变更调用，并触发纠正性验证；随后拦截解除，直到新的用户轮次。这种设计并未授权或重放已拒绝的调用，而是让执行循环继续。</p><p>附录 I.2（重试压力实验部分）的作者实验报告，同轮强制重试、切换工具以及纠正验证器异常后的重试能够继续；新的用户轮次会重新启用拦截，反复的未授权转移仍被阻止。不同动作的策略并不相同，不能把“会拦截”概括成所有调用都会重复受检。<a href="https://arxiv.org/html/2608.19861v2" target="_blank" rel="noreferrer">论文正文与附录</a></p><p>论文的完整干预覆盖定理另有更强前提：理想验证器在事件提交前作出绑定裁决，被拒事件不能提交。该前提不能直接替代实际采用的概率验证器与边界触发策略。这里比较的是合同，不是以定理替实现作担保。</p><h2 id="裁决核心之外-还有宿主责任" tabindex="-1">裁决核心之外，还有宿主责任 <a class="header-anchor" href="#裁决核心之外-还有宿主责任" aria-label="Permalink to &quot;裁决核心之外，还有宿主责任&quot;">​</a></h2><p>Microsoft Agent Governance Toolkit（微软智能体治理工具集）的已读策略引擎说明，宿主每次提供完整快照，运行核心不保留影响后续裁决的可变状态；相同清单、快照、模式与调度输出得到相同裁决。运行核心失败返回拒绝，并且不实施变换。调用拦截与裁决执行仍由宿主负责。<a href="https://github.com/microsoft/agent-governance-toolkit/blob/main/policy-engine/README.md" target="_blank" rel="noreferrer">策略引擎说明</a></p><p>两者并非同一个实验的参赛方案。论文作者支持其纠正策略的陈述，工具集维护者支持另一种宿主合同的文档陈述；它们是两个独立撰写的来源，却没有相互复现，也没有共同的性能或安全测试。</p><p>同一说明还写明，遥测接收端异常会被吞掉。这个细节说明“出错即拒绝”必须写清错误所在的责任边界：策略执行失败应拒绝，并不意味着任何日志故障都应终止操作。把所有异常统称为一种安全语义，会掩盖实际负责阻止副作用的组件。</p><h2 id="内部模型只回答一个重试问题" tabindex="-1">内部模型只回答一个重试问题 <a class="header-anchor" href="#内部模型只回答一个重试问题" aria-label="Permalink to &quot;内部模型只回答一个重试问题&quot;">​</a></h2><p>同日分析阶段已经执行一个按论文规则手工转写的状态模型：授权条件始终为不允许，初始拦截启用，分别追加 1、3、10 次同轮重试。首次调用均被阻止，追加重试在建议式模型中全部继续。对照模型在每次调用前重复检查，因此全部阻止。新用户轮次重新启用拦截；验证器异常本身不重新启用它。</p><p>这是内部实验依据，说明指定状态转换如何影响覆盖范围。对照是脚本中的假设性持续检查实现，既不是微软工具集，也没有执行论文代码、作者保存的检查点或完整任务基准。它不提供模型成功率、延迟、部署安全性或产品优劣排名。<a href="/joinwell52/assets/evidence/2026-11-28-sig-20261128-001/experiment-evidence.json">内部模型方法与逐事件输出</a>保留了输入、对照及局限。</p><p>最小反例可以用一个序列检查：拒绝写入 → 同轮重试 → 观察真正产生副作用的位置。若只测试第一步，两个合同看起来一样；第二步才暴露持续裁决是否存在。这是本研究的工程解释，而不是新增的端到端测量。</p><h2 id="把验证要求放到副作用发生处" tabindex="-1">把验证要求放到副作用发生处 <a class="header-anchor" href="#把验证要求放到副作用发生处" aria-label="Permalink to &quot;把验证要求放到副作用发生处&quot;">​</a></h2><p>对需要持续授权的系统，可以把下面的责任链用作审查问题，而不能把它当作两个项目已经实现的统一流程：</p><table tabindex="0"><thead><tr><th>阶段</th><th>责任主体与输入</th><th>应取得的输出</th><th>未取得时的处理</th></tr></thead><tbody><tr><td>准备裁决</td><td>宿主收集目标、参数与当前状态</td><td>对本次调用有效的快照</td><td>停止该调用并补全输入</td></tr><tr><td>作出裁决</td><td>策略核心读取快照与规则</td><td>明确允许或拒绝</td><td>按该决策边界处理异常</td></tr><tr><td>执行副作用</td><td>宿主将裁决绑定到实际调用</td><td>已拒请求无法到达变更入口</td><td>记录旁路并停止放行</td></tr><tr><td>重试与恢复</td><td>宿主重新确认状态和授权</td><td>重试有自己的有效裁决</td><td>不复用已经失效的允许</td></tr></tbody></table><p>这是建议的审查链。实践中的下一项证据应是实际入口清单，以及每个入口在首次拒绝、同轮重试、换工具、验证器异常和新用户轮次下的结果。只展示策略核心返回拒绝，还不能回答宿主是否漏掉某个入口。</p><h2 id="持续检查的收益与代价都未测完" tabindex="-1">持续检查的收益与代价都未测完 <a class="header-anchor" href="#持续检查的收益与代价都未测完" aria-label="Permalink to &quot;持续检查的收益与代价都未测完&quot;">​</a></h2><p>建议式纠正有合理用途：允许执行者恢复，避免同一错误反复中断。持续检查也可能带来等待、误拒绝或活性损失。内部模型采用恒定授权条件和单线程执行，无法比较这些代价，更不能据此推荐替换某个产品。</p><p>本次缺少论文固定源码与保存检查点，也没有工具集固定宿主、适配器及实际拒绝记录。因而尚不清楚具体部署能否持续覆盖每条重试路径。平台评审可以先要求明确“哪类动作、哪次调用、哪种异常由谁阻止”，再用真实入口测试回答。已有文档与内部模型支持责任区分，尚不支持无旁路或普遍有效的结论。</p><p>来源角色说明：论文结果是作者自报；工具集说明是维护者对自身合同的陈述；本研究模型是内部实验；责任链是研究解释与建议。发表、引用和实现存在均不能自动提升为独立验证。本次未生成社区版，因为尚无足够的真实宿主证据支撑面向特定社区的独立讨论角度。</p>',22))])}const f=i(l,[["render",c]]);export{b as __pageData,f as default};
